-- CF-CHG-20260915-247 Layer 3 model routing (Platform Admin direction 29 Sep 2026 18:30 IST): FRESH HOLDOUT gold sets.
-- Read by hand from the stored page text AFTER the task contracts were frozen (pipeline.layer3_task_contract_freezes,
-- 29 Sep 2026 13:31 UTC) and BEFORE any model ran on these pages. No prompt, schema or validator was changed after
-- reading them. Every case pins the page text by its SHA-256 (the text the qualification run and the live worker read)
-- and, for stated cases, a verbatim excerpt. Sets are frozen by the next migration (digest), and a run is refused if a
-- set changes after freezing.
--
-- Random sampling (deterministic, reproducible): order candidates by md5('<seed>:'||course_id), keep the first course
-- per provider, take the first N. Seeds and queries are recorded on pipeline.layer3_holdout_sets.
--  l3r-intake-h1  (seed l3r-intake-h1, N=48): coverage-sweep pages that print the course CRICOS code, active course,
--     not Layer 4-blocked, course holds no active intake, course NOT in either earlier intake gold set (a3-dev-1,
--     a3-holdout-1). 48 providers. One page left out as unclear (Gordon TAFE: "February" intake with January class
--     start dates). 47 cases: 13 with months, 34 not stated.
--  l3r-english-h1 (seed l3r-english-h1, N=38): same page population, course holds no active English requirement and
--     the Layer 2 extractor found no clear IELTS/PTE/TOEFL value (none or unclear). 38 providers. One left out as
--     unclear (Austra College: band table with score ranges). 37 cases: 19 stated, 18 not stated.
--  l3r-tuition-h1 (seed l3r-tuition-h1, N=36): courses already handed off to the live tuition route (work item
--     admitted or held for Layer 4), with the hand-off's plain-text evidence and its candidate context (copied from the
--     work item below). 36 providers; 6 admitted and 30 Layer 4-held by the live route. 36 cases: 8 where the target is
--     the international annual tuition stated per year, 28 where it is not (totals, per semester, domestic, salaries).
-- Conventions: intakes as in a3-holdout-1 (months this course starts for international students; census, orientation,
-- application and event dates are not intakes; terms without months, rolling/monthly/contact-us are not stated).
-- English: the minimum IELTS Academic overall (and each-band minimum if stated), PTE Academic and TOEFL iBT overall for
-- direct entry of international students. Tuition: admit only when the target is the international tuition stated as
-- annual/per year beside the amount; fee_year only when printed with the amount.

create temporary table _gold(gold_set text, task_class text, case_key text, course_id uuid, evidence_id uuid, text_sha256 text, gold jsonb, excerpt text, notes text) on commit drop;

select g.gold_set, g.case_key, g.task_class, g.course_id, p.provider_id, g.evidence_id,
       case when g.task_class='provider_current_tuition_validation' then coalesce(e.source_url,p.url) else p.url end,
       g.text_sha256, g.gold, g.excerpt,
       case when g.task_class='provider_current_tuition_validation' then w.candidate_context end, g.notes
  from _gold g
  join pipeline.coverage_course_pages p on p.course_id=g.course_id
  join pipeline.evidence_artifacts e on e.id=g.evidence_id
  left join pipeline.layer3_work_items w on w.id=p.l3_work_item_id
on conflict (case_key) do nothing;

-- identity checks: the evidence is the page read by hand (intake, English) or the hand-off text (tuition)
do $v$
declare n int; bad int;
begin
  select count(*) into n from pipeline.layer3_holdout_cases where gold_set in ('l3r-intake-h1','l3r-english-h1','l3r-tuition-h1');
  if n<>120 then raise exception 'expected 120 holdout cases, found %', n; end if;
  select count(*) into bad from pipeline.layer3_holdout_cases c join pipeline.coverage_course_pages p on p.course_id=c.course_id
   left join pipeline.layer3_work_items w on w.id=p.l3_work_item_id
   where c.gold_set in ('l3r-intake-h1','l3r-english-h1','l3r-tuition-h1')
     and ((c.task_class<>'provider_current_tuition_validation' and c.evidence_id<>p.evidence_id)
       or (c.task_class='provider_current_tuition_validation' and (w.evidence_id is distinct from c.evidence_id or c.candidate_context is null)));
  if bad>0 then raise exception '% holdout cases do not match their page evidence or hand-off', bad; end if;
  -- disjoint from the earlier intake gold sets
  if exists (select 1 from pipeline.layer3_holdout_cases c join pipeline.layer3_intake_benchmark_cases b on b.course_id=c.course_id where c.gold_set='l3r-intake-h1') then
    raise exception 'intake holdout overlaps an earlier intake gold set'; end if;
end $v$;
